def has_cycle(num_nodes: int, edges: list) -> bool:
    graph = {i: [] for i in range(num_nodes)}
    for u, v in edges:
        graph[u].append(v)

    state = [0] * num_nodes # 0=Unvisited, 1=Visiting, 2=Visited

    def dfs(u):
        state[u] = 1 # Mark in current recursion stack
        for v in graph[u]:
            if state[v] == 1: # Back edge found!
                return True
            if state[v] == 0 and dfs(v):
                return True
        state[u] = 2 # Fully processed
        return False

    for node in range(num_nodes):
        if state[node] == 0 and dfs(node):
            return True
    return False

# Test: 3 nodes, edges [[0,1], [1,2], [2,0]] -> Returns True

