    int currMax = nums[0], globalMax = nums[0];
    for (int i = 1; i < numsSize; i++) {
        currMax = (nums[i] > currMax + nums[i]) ? nums[i] : currMax + nums[i];
        if (currMax > globalMax) globalMax = currMax;
    }
    return globalMax;
}

