class LRUCache {
    class Node { int key, value; Node prev, next; }
    private HashMap<Integer, Node> map = new HashMap<>();
    private int cap;
    private Node head, tail;

    public LRUCache(int capacity) {
        this.cap = capacity;
        head = new Node(); tail = new Node();
        head.next = tail; tail.prev = head;
    }
}

